"""BADANG Trading v1.7.2 read-only dashboard. No DB or order execution."""
from flask import Blueprint, Response

badang_dashboard = Blueprint('badang_dashboard', __name__)

HTML = r'''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>BADANG Trading | Dashboard</title>
<style>
:root{color-scheme:dark;font-family:system-ui,-apple-system,'Malgun Gothic',sans-serif;background:#0b1220;color:#eef4ff}*{box-sizing:border-box}body{margin:0}main{max-width:1200px;margin:auto;padding:24px 16px 70px}header,.toolbar,.cards,.stats,.meta{display:flex;align-items:center;gap:12px;flex-wrap:wrap}header{justify-content:space-between;margin-bottom:24px}h1{font-size:clamp(24px,4vw,34px);margin:0}h2{font-size:18px;margin:0 0 12px}.muted{color:#98a8c1}.sub{font-size:13px}.panel,.card{background:#141f32;border:1px solid #293a55;border-radius:16px;padding:18px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:18px 0}.stats .panel{padding:16px}.number{font-size:28px;font-weight:750;margin-top:4px}.toolbar{margin:16px 0}button,select{background:#1c2b42;color:#edf4ff;border:1px solid #38506d;border-radius:9px;padding:10px 13px;font:inherit}button{cursor:pointer}button.primary{background:#2563eb;border-color:#2563eb}button:disabled{opacity:.6;cursor:wait}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(285px,1fr));align-items:stretch}.card{min-width:0}.head{display:flex;align-items:center;justify-content:space-between;gap:8px}.coin{font-size:20px;font-weight:750}.badge{padding:5px 9px;border-radius:7px;font-size:12px;font-weight:800;background:#374151}.LONG{background:#124c3e;color:#8df1cc}.SHORT{background:#63303a;color:#ffb1bc}.WAIT{background:#364152;color:#d6deeb}.price{font-size:25px;font-weight:750;margin:13px 0 3px;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:16px 0}.metric{background:#10192a;border-radius:9px;padding:10px}.metric .val{font-weight:650;margin-top:4px;overflow-wrap:anywhere}.warn{color:#ffd28a}.up{color:#8df1cc}.down{color:#ffacb7}.foot{border-top:1px solid #30405a;margin-top:13px;padding-top:12px}.error{color:#ffb2b2}.empty{padding:26px;text-align:center}.detail{margin-top:12px}.detail summary{cursor:pointer;color:#a9c7ff}.detail pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;color:#becbe0}a{color:#9cc3ff}@media(max-width:550px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:18px 12px 50px}.panel,.card{padding:14px}}
</style></head><body><main>
<header><div><h1>🌊 BADANG <span style="color:#75b5ff">Trading</span></h1><div class="muted sub">v1.7.2 · 실시간 요청형 분석 대시보드 · 자동매매 아님</div></div><a href="/">기존 화면 ↗</a></header>
<section class="stats"><div class="panel"><div class="muted sub">조회 완료</div><div class="number" id="total">–</div></div><div class="panel"><div class="muted sub">LONG</div><div class="number up" id="long">–</div></div><div class="panel"><div class="muted sub">SHORT</div><div class="number down" id="short">–</div></div><div class="panel"><div class="muted sub">WAIT</div><div class="number" id="wait">–</div></div></section>
<section class="panel"><div class="toolbar"><label>분석 모드 <select id="mode"><option value="scalp">단타 (15m·30m·1H)</option><option value="swing">스윙 (1H·4H·1D)</option></select></label><button class="primary" id="load">분석 새로고침</button><button id="next" disabled>다음 5종목</button></div><div id="status" class="muted sub" role="status">분석을 시작하려면 새로고침을 눌러줘.</div><div id="updated" class="muted sub" style="margin-top:5px"></div></section>
<div class="meta" style="justify-content:space-between;margin:22px 0 12px"><h2>종목별 분석</h2><div class="muted sub" id="range">최대 5종목씩 조회</div></div><div class="cards" id="cards"><div class="panel empty muted">데이터를 불러오지 않았어.</div></div>
<p class="muted sub" style="margin-top:24px">OI는 현재 계약 수량이며 변화율이 아닙니다. 체결 압력은 최근 최대 500건의 표본으로 전체 CVD가 아닙니다. VWAP은 봉 기반 근삿값입니다. 모든 판단은 연구용이며 투자 수익을 보장하지 않습니다.</p>
</main><script>
'use strict';
const $=id=>document.getElementById(id);let offset=0,busy=false;
const esc=x=>String(x??'–').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=4)=>n===null||n===undefined||n===''||!Number.isFinite(Number(n))?'–':Number(n).toLocaleString('en-US',{maximumFractionDigits:d});
const pct=n=>n===null||n===undefined?'–':fmt(Number(n)*100,4)+'%';
const trend=t=>t==='UP'?'<span class="up">상승 ↑</span>':t==='DOWN'?'<span class="down">하락 ↓</span>':esc(t||'–');
const metric=(label,value)=>`<div class="metric"><div class="muted sub">${esc(label)}</div><div class="val">${value}</div></div>`;
function render(x){const r=x.v17_research||{},v=r.vwap||{},c=r.checks||{},w=x.stability_warnings||[],s=['LONG','SHORT'].includes(x.recommendation)?x.recommendation:'WAIT';const ts=Object.entries(x.timeframe_trends||{}).map(([k,val])=>`${esc(k)} ${trend(val)}`).join(' · ')||'–';const issues=[...w];if(x.trendline_warning)issues.push('추세선 경고');if(x.divergence_warning)issues.push('다이버전스 주의');if(r.data_status!=='OK')issues.push('파생상품 데이터 미확인');if(r.oi_change_status==='NOT_COMPUTED_NO_HISTORY')issues.push('OI 변화율 계산 불가');
return `<article class="card"><div class="head"><span class="coin">${esc(x.symbol||'UNKNOWN')}</span><span class="badge ${s}">${s}</span></div><div class="price">$${fmt(x.entry_reference,8)}</div><div class="muted sub">${esc(x.exchange||'–')} · ${ts}</div><div class="grid">${metric('RSI',fmt(x.rsi,2))}${metric('점수 (롱 / 숏)',`${fmt(x.long_score,0)} / ${fmt(x.short_score,0)}`)}${metric('현재 OI (OKX)',fmt(r.oi_contracts,2))}${metric('펀딩비 (OKX)',pct(r.funding_rate))}${metric('최근 체결 불균형',r.sample_imbalance==null?'–':fmt(r.sample_imbalance,3))}${metric('VWAP (근사)',fmt(v.value,8))}${metric('손절 기준',fmt(x.stop_loss,8))}${metric('1차 목표',fmt(x.take_profit_1,8))}</div><div class="sub muted">2차 목표: ${fmt(x.take_profit_2,8)} · 표본: ${fmt(r.trade_sample_count,0)}건 · 표본 기간: ${fmt(r.sample_span_seconds,1)}초</div><div class="foot sub">${issues.length?`<div class="warn">⚠ ${issues.map(esc).join(' · ')}</div>`:'<span class="muted">추가 안정화 경고 없음</span>'}<div class="muted" style="margin-top:7px">${esc((x.reasons||[]).join(' · ')||'판단 근거 미제공')}</div><details class="detail"><summary>분석 원본 상세 보기</summary><pre>${esc(JSON.stringify(x,null,2))}</pre></details></div></article>`}
async function load(next=false){if(busy)return;busy=true;const button=$('load'),nextButton=$('next');button.disabled=true;nextButton.disabled=true;const at=next?offset+5:0;$('status').textContent='거래소 데이터를 조회 중이야. 종목당 여러 API 요청으로 시간이 걸릴 수 있어…';try{const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),110000);let response;try{response=await fetch(`/api/v13-scan?mode=${encodeURIComponent($('mode').value)}&offset=${at}`,{cache:'no-store',signal:ctl.signal});}finally{clearTimeout(timer)}if(!response.ok)throw new Error(`서버 HTTP ${response.status}`);const data=await response.json();if(data.error)throw new Error(data.error);const rows=Array.isArray(data.results)?data.results:[];offset=at;$('total').textContent=rows.length;$('long').textContent=rows.filter(x=>x.recommendation==='LONG').length;$('short').textContent=rows.filter(x=>x.recommendation==='SHORT').length;$('wait').textContent=rows.filter(x=>!['LONG','SHORT'].includes(x.recommendation)).length;$('cards').innerHTML=rows.length?rows.map(render).join(''):'<div class="panel empty muted">이번 조회에 표시할 종목이 없어.</div>';$('range').textContent=`전체 ${fmt(data.total,0)}종목 중 ${at+1}~${at+rows.length}번째`;const errors=Array.isArray(data.errors)?data.errors:[];$('status').textContent=`${rows.length}종목 조회 완료${errors.length?` · 오류 ${errors.length}건`:''}`;if(errors.length){$('status').textContent+=' · '+errors.map(e=>`${e.symbol}: ${e.error}`).join(' / ').slice(0,220)}$('updated').textContent='마지막 조회: '+new Date().toLocaleString('ko-KR');nextButton.disabled=!(data.next_offset<data.total);}catch(e){$('status').innerHTML=`<span class="error">조회 실패: ${esc(e.message)}</span>`;nextButton.disabled=true;}finally{busy=false;button.disabled=false}}
$('load').addEventListener('click',()=>load(false));$('next').addEventListener('click',()=>load(true));$('mode').addEventListener('change',()=>{$('cards').innerHTML='<div class="panel empty muted">모드가 바뀌었어. 분석 새로고침을 눌러줘.</div>';$('next').disabled=true;offset=0});
</script></body></html>'''

@badang_dashboard.get('/dashboard')
def dashboard():
    return Response(HTML, mimetype='text/html; charset=utf-8', headers={'Cache-Control': 'no-store'})
